package com.cleancity;
import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import java.util.*; import org.mindrot.jbcrypt.BCrypt;
@WebServlet("/api/auth/*") public class AuthServlet extends HttpServlet {
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{String p=req.getPathInfo(); Map<String,String> b=Json.gson.fromJson(req.getReader(),Map.class); try(Connection c=DB.get()){if("/register".equals(p)){String name=b.get("name"),email=b.get("email"),pw=b.get("password");if(name==null||email==null||pw==null||pw.length()<6){Json.error(res,400,"Enter valid details. Password must be 6+ characters.");return;} PreparedStatement s=c.prepareStatement("INSERT INTO users(name,email,password_hash) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS);s.setString(1,name);s.setString(2,email.toLowerCase());s.setString(3,BCrypt.hashpw(pw,BCrypt.gensalt()));s.executeUpdate();try(ResultSet k=s.getGeneratedKeys()){k.next();req.getSession().setAttribute("uid",k.getInt(1));req.getSession().setAttribute("role","USER");Json.send(res,Map.of("ok",true,"id",k.getInt(1),"name",name,"role","USER"));}}else if("/login".equals(p)){String email=b.get("email"),pw=b.get("password");PreparedStatement s=c.prepareStatement("SELECT id,name,password_hash,role FROM users WHERE email=?");s.setString(1,email.toLowerCase());ResultSet x=s.executeQuery();if(!x.next()||!BCrypt.checkpw(pw,x.getString(3))){Json.error(res,401,"Invalid email or password");return;}req.getSession().setAttribute("uid",x.getInt(1));req.getSession().setAttribute("role",x.getString(4));Json.send(res,Map.of("ok",true,"id",x.getInt(1),"name",x.getString(2),"role",x.getString(4)));}}catch(SQLIntegrityConstraintViolationException e){Json.error(res,409,"Email already registered");}catch(Exception e){e.printStackTrace();Json.error(res,500,"Server/database error");}}
 protected void doGet(HttpServletRequest req,HttpServletResponse res)throws IOException{HttpSession s=req.getSession(false);if(s==null||s.getAttribute("uid")==null){Json.send(res,Map.of("loggedIn",false));return;}Json.send(res,Map.of("loggedIn",true,"id",s.getAttribute("uid"),"role",s.getAttribute("role")));}
 protected void doDelete(HttpServletRequest req,HttpServletResponse res)throws IOException{HttpSession s=req.getSession(false);if(s!=null)s.invalidate();Json.send(res,Map.of("ok",true));}
}
